diff --git a/scripts/test-operation-fork-executors.js b/scripts/test-operation-fork-executors.js
index 4adcc63..ef8ba3c 100644
--- a/scripts/test-operation-fork-executors.js
+++ b/scripts/test-operation-fork-executors.js
@@ -205,6 +205,14 @@ const tamperedComparison = forks.compareFork(tamperedFork,
 const tamperedBranch = tamperedComparison.branches.find((branch) => branch.branch_id === 'branch-claude-sonnet');
 assert.equal(tamperedBranch.comparable, false);
 assert(tamperedBranch.reasons.includes('fork-receipt-unverified'));
+// Its telemetry still names the requested model and carries numbers, but an
+// unbound observation proves nothing: model and every metric fall back to unknown.
+assert.equal(tamperedBranch.executor.model_status, 'unknown');
+assert.equal(tamperedBranch.executor.model_reason_code, 'MODEL_OBSERVATION_UNTRUSTED');
+assert.deepEqual([tamperedBranch.executor.cost, tamperedBranch.executor.duration_ms,
+  tamperedBranch.executor.tokens], [null, null, null]);
+assert.deepEqual([tamperedBranch.executor.cost_status, tamperedBranch.executor.duration_status,
+  tamperedBranch.executor.tokens_status], ['unknown', 'unknown', 'unknown']);
 const tamperedProof = forks.buildProofReport(tamperedFork, forks.readEvents(project, 'fork-executors'),
   { evidence: forks.forkEvidence(project, tamperedFork) });
 assert.equal(tamperedProof.report.summary.verified_receipt_count, 2);
@@ -269,6 +277,68 @@ assert.equal(resultTamperedProof.report.summary.verified_receipt_count, 2);
 assert.equal(resultTamperedProof.report.summary.comparable_count, 2);
 fs.writeFileSync(manifestFile, manifestOriginal);

+// Adversarial model substitution. branch-codex-hosted was asked for gpt-5-codex
+// and its trusted telemetry names gpt-4.1. The proof states that plainly, and
+// the telemetry that branch never reported stays unknown instead of borrowing
+// the unsigned numbers carried on the fork record.
+const substituted = byId.get('branch-codex-hosted');
+assert.equal(substituted.requested_model, 'gpt-5-codex');
+assert.equal(substituted.observed_model, 'gpt-4.1');
+assert.equal(substituted.model_status, 'failed');
+assert.equal(substituted.model_reason_code, 'MODEL_OBSERVATION_MISMATCH');
+assert.equal(substituted.receipt_status, 'verified',
+  'substitution is a model proof failure, not a receipt failure');
+assert.equal(fork.branches.find((branch) => branch.branch_id === 'branch-codex-hosted').duration_ms, 1000);
+assert.deepEqual([substituted.duration_ms, substituted.tokens, substituted.cost], [null, null, null]);
+assert.deepEqual([substituted.duration_status, substituted.tokens_status, substituted.cost_status],
+  ['unknown', 'unknown', 'unknown']);
+for (const state of states) {
+  if (state.model_status === 'passed') assert.equal(state.observed_model, state.requested_model);
+}
+
+// The public artifacts disclose the substitution rather than hiding it.
+const substitutedPublic = replay.replay.branches
+  .find((branch) => branch.branch_id === 'branch-codex-hosted').executor;
+assert.equal(substitutedPublic.model_status, 'failed');
+assert.equal(substitutedPublic.model_reason_code, 'MODEL_OBSERVATION_MISMATCH');
+assert.equal(substitutedPublic.observed_model, 'gpt-4.1');
+assert.deepEqual([substitutedPublic.duration_status, substitutedPublic.tokens_status,
+  substitutedPublic.cost_status], ['unknown', 'unknown', 'unknown']);
+assert(proof.serialized.includes('gpt-4.1'), 'the proof report must disclose the observed model');
+
+// Rewriting the requested model to match what actually ran cannot launder the
+// failure into a pass. The executor set digest, the bound branch profile digest,
+// and the signed receipt binding each refuse in turn.
+const executorFile = path.join(project, '.planning', 'operation-forks', 'fork-executors', 'executors.json');
+const executorOriginal = fs.readFileSync(executorFile, 'utf8');
+const launderedFile = JSON.parse(executorOriginal);
+const launderedProfile = launderedFile.executors.find((profile) => profile.profile_id === 'codex-hosted');
+launderedProfile.model = 'gpt-4.1';
+fs.writeFileSync(executorFile, `${JSON.stringify(launderedFile, null, 2)}\n`);
+assert.throws(() => forks.forkEvidence(project, forks.loadFork(project, 'fork-executors')),
+  (error) => error.code === 'FORK_EXECUTOR_SET_MISMATCH');
+
+const launderedManifest = JSON.parse(manifestOriginal);
+launderedManifest.executor_set_digest = forks.executorSetDigest(launderedFile);
+fs.writeFileSync(manifestFile, `${JSON.stringify(launderedManifest, null, 2)}\n`);
+assert.throws(() => forks.forkEvidence(project, forks.loadFork(project, 'fork-executors')),
+  (error) => error.code === 'FORK_EXECUTOR_PROFILE_MISMATCH');
+
+launderedManifest.branches.find((branch) => branch.branch_id === 'branch-codex-hosted')
+  .executor_profile_digest = forks.executorProfileDigest(launderedProfile);
+fs.writeFileSync(manifestFile, `${JSON.stringify(launderedManifest, null, 2)}\n`);
+const launderedState = forks.executorStates(project, forks.loadFork(project, 'fork-executors'))
+  .find((state) => state.branch_id === 'branch-codex-hosted');
+assert.equal(launderedState.requested_model, 'gpt-4.1');
+assert.equal(launderedState.model_status, 'unknown',
+  'a rewritten executor set may lose the proof, never win it');
+assert.equal(launderedState.model_reason_code, 'MODEL_OBSERVATION_UNTRUSTED');
+assert.equal(launderedState.observed_model, null);
+assert.equal(launderedState.receipt_status, 'failed');
+assert.equal(launderedState.receipt_reason_code, 'FORK_RECEIPT_BINDING_MISMATCH');
+fs.writeFileSync(executorFile, executorOriginal);
+fs.writeFileSync(manifestFile, manifestOriginal);
+
 // A verified branch selects, and landing still refuses to run without a fresh
 // verification of that same binding.
 const restored = forks.loadFork(project, 'fork-executors');
